"use client";

import { Button } from "@base-ui/react/button";
import { Checkbox } from "@base-ui/react/checkbox";
import { Tabs } from "@base-ui/react/tabs";
import { Check, Download, Undo2 } from "lucide-react";
import { Fragment, useRef, useState, type ReactNode } from "react";
import "../shared/inter";
import "./styles.css";

type Sheet = "invoice" | "credit";
export interface InvoiceLine { id: string; name: string; qty: number; rate: number; tax: number; group?: string }
export interface InvoiceParty { name: string; lines: string[] }
export interface InvoiceCreditProps {
  seller?: InvoiceParty;
  buyer?: InvoiceParty;
  invoiceNo?: string;
  creditNo?: string;
  invoiceDate?: string;
  dueDate?: string;
  period?: string;
  lines?: InvoiceLine[];
  currency?: string;
  onIssue?: (credits: Record<string, number>, total: number) => void;
  payHref?: string;
  onDownload?: (sheet: Sheet) => void;
  appearance?: "clean" | "classic";
  className?: string;
}

const demoLines: InvoiceLine[] = [
  { id: "plan", name: "Growth plan", qty: 1, rate: 1250, tax: .2 },
  { id: "seats", name: "Extra seats", qty: 12, rate: 40, tax: .2 },
  { id: "api", name: "API calls (per 1k)", qty: 18420, rate: .42, tax: .2, group: "Metered usage" },
];
const demoSeller = { name: "Lumen Labs, Inc.", lines: ["48 Harbour Street", "Bristol", "BS1 4RN", "United Kingdom"] };
const demoBuyer = { name: "Northwind Logistics GmbH", lines: ["Speicherstraße 12", "Hamburg", "20457", "Germany"] };

function moneyFormat(currency: string) {
  const isCode = /^[a-z]{3}$/i.test(currency);
  const format = new Intl.NumberFormat("en-US", isCode ? { style: "currency", currency } : { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const precision = format.resolvedOptions().maximumFractionDigits ?? 2;
  const numbers = new Intl.NumberFormat("en-US", { minimumFractionDigits: precision, maximumFractionDigits: precision });
  const code = isCode ? currency.toUpperCase() : ({ "$": "USD", "£": "GBP", "€": "EUR", "¥": "JPY" } as Record<string,string>)[currency];
  return {
    code, precision, symbol: isCode ? format.formatToParts(0).find(part => part.type === "currency")?.value ?? currency : currency,
    number: (n: number) => numbers.format(n),
    round: (n: number) => Math.round((n + Number.EPSILON) * 10 ** precision) / 10 ** precision,
    money: (n: number) => isCode ? format.format(n) : `${n < 0 ? "-" : ""}${currency}${numbers.format(Math.abs(n))}`,
  };
}

function valid(n: number) { return Number.isFinite(n) ? n : 0; }
function clampCredit(amount: number, total: number) {
  return Math.max(Math.min(total, 0), Math.min(Math.max(total, 0), amount));
}

function Party({ party, label }: { party: InvoiceParty; label: string }) {
  return <div><h3 className="ki-label">{label}</h3><strong>{party.name}</strong>{party.lines.map((line,i) => <p key={i}>{line}</p>)}</div>;
}

function Terms({ fields }: { fields: [string, ReactNode][] }) {
  return <section className="ki-terms"><h3 className="ki-label">Terms</h3><dl>{fields.map(([label, value]) => value ? <div key={label}><dt>{label}</dt><dd>{value}</dd></div> : null)}</dl></section>;
}

function SheetHead({ title, brand, children }: { title: string; brand: string; children: ReactNode }) {
  return <header className="ki-head"><div><h2>{title}</h2><div className="ki-sub">{children}</div></div><div className="ki-brand"><i aria-hidden="true" />{brand}</div></header>;
}

function CreditInput({ amount, total, name, disabled, format, onCommit }: {
  amount: number; total: number; name: string; disabled: boolean; format: ReturnType<typeof moneyFormat>; onCommit: (value: number) => void;
}) {
  const [draft, setDraft] = useState<string | null>(null);
  const canceled = useRef(false);
  const display = draft ?? format.number(amount);
  return (
    <label className="ki-field" data-disabled={disabled ? "" : undefined}>
      <span aria-hidden="true">{format.symbol}</span>
      <input aria-label={`Credit amount for ${name}`} type="text" inputMode="decimal" disabled={disabled} value={display}
        style={{ width: `${Math.min(15, Math.max(1, display.length + .35))}ch` }}
        onFocus={event => { canceled.current = false; event.currentTarget.select(); }}
        onChange={event => setDraft(event.target.value)}
        onBlur={() => {
          if (draft !== null && !canceled.current) {
            const numeric = Number(draft.replace(/,/g, "").trim());
            if (Number.isFinite(numeric)) onCommit(format.round(clampCredit(numeric, total)));
          }
          setDraft(null);
        }}
        onKeyDown={event => {
          if (event.key === "Enter" || event.key === "Escape") {
            event.preventDefault();
            canceled.current = event.key === "Escape";
            event.currentTarget.blur();
          }
        }}
      />
    </label>
  );
}

function InvoiceDocument({
  seller = demoSeller, buyer = demoBuyer, invoiceNo = "INV-2041", creditNo = "CN-0117", invoiceDate = "1 Oct 2026",
  dueDate = "31 Oct 2026", period = "1 Sep – 30 Sep 2026", lines = demoLines, currency = "$", onIssue,
  payHref, onDownload, appearance = "clean", className,
}: InvoiceCreditProps) {
  const [sheet, setSheet] = useState<Sheet>("invoice");
  const [issued, setIssued] = useState(false);
  const [paymentNotice, setPaymentNotice] = useState(false);
  const [edits, setEdits] = useState<Record<string, { selected?: boolean; amount?: number }>>({});
  const rootRef = useRef<HTMLDivElement>(null);
  const invoiceTab = useRef<HTMLButtonElement>(null);
  const creditTab = useRef<HTMLButtonElement>(null);
  const format = moneyFormat(currency);
  const rows = lines.map(line => {
    const total = format.round(valid(line.qty) * valid(line.rate));
    const selected = edits[line.id]?.selected ?? true;
    return { ...line, total, selected, amount: clampCredit(edits[line.id]?.amount ?? total, total) };
  });
  const subtotal = format.round(rows.reduce((sum, row) => sum + row.total, 0));
  const tax = format.round(rows.reduce((sum, row) => sum + row.total * valid(row.tax), 0));
  const credits = rows.filter(row => row.selected);
  const creditSubtotal = format.round(credits.reduce((sum, row) => sum + row.amount, 0));
  const creditTax = format.round(credits.reduce((sum, row) => sum + row.amount * valid(row.tax), 0));
  const creditTotal = format.round(creditSubtotal + creditTax);

  function switchSheet(value: Sheet) {
    setSheet(value);
    (value === "invoice" ? invoiceTab : creditTab).current?.focus({ preventScroll: true });
  }

  function updateLine(id: string, change: { selected?: boolean; amount?: number }) {
    setEdits(current => ({ ...current, [id]: { ...current[id], ...change } }));
  }

  function download() {
    if (onDownload) { onDownload(sheet); return; }
    const root = rootRef.current;
    if (!root) return;
    root.dataset.printing = "";
    try { window.print(); } finally { delete root.dataset.printing; }
  }

  return (
    <Tabs.Root ref={rootRef} className={["kalos-invoice",className].filter(Boolean).join(" ")} data-appearance={appearance}
      value={sheet} onValueChange={value => setSheet(value as Sheet)}>
      <div className="ki-bar">
        <Tabs.List className="ki-tabs" aria-label="Document" activateOnFocus>
          <Tabs.Indicator className="ki-tab-chip" />
          <Tabs.Tab value="invoice" ref={invoiceTab}>Invoice</Tabs.Tab><Tabs.Tab value="credit" ref={creditTab}>Credit note</Tabs.Tab>
        </Tabs.List>
        <div className="ki-actions">
          <Button className="ki-btn" onClick={download}><Download />PDF</Button>
          {sheet === "invoice" && <Button className="ki-btn" onClick={() => switchSheet("credit")}><Undo2 />Credit invoice</Button>}
        </div>
      </div>
      <div className="ki-stack">
        <Tabs.Panel value="invoice" keepMounted hidden={false} className="ki-sheet" data-front={sheet === "invoice"} aria-hidden={sheet !== "invoice"} tabIndex={-1}>
          <SheetHead title={format.money(subtotal + tax)} brand={seller.name}>
            {dueDate && <span>Due {dueDate}</span>}
            {payHref ? <a className="ki-link" href={payHref}>Pay online</a> : <Button className="ki-link" onClick={() => setPaymentNotice(true)}>Pay online</Button>}
            {paymentNotice && <span role="status">Demo invoice · no payment required</span>}
          </SheetHead>
          <div className="ki-parties"><Party party={seller} label="From" /><Party party={buyer} label="To" /></div>
          <Terms fields={[
            ["Invoice no", invoiceNo && <span className="ki-ref">{invoiceNo}</span>], ["Invoice date", invoiceDate], ["Due date", dueDate], ["Billing period", period],
          ]} />
          <table className="ki-items" aria-label="Invoice items">
            <thead><tr><th>Name</th><th>Qty</th><th className="ki-extra">Rate</th><th className="ki-extra">Tax</th><th>Price</th></tr></thead>
            <tbody>{rows.map((row,i) => (
              <Fragment key={row.id}>
                {row.group && row.group !== rows[i-1]?.group && <tr className="ki-group"><th colSpan={5} scope="rowgroup">{row.group}</th></tr>}
                <tr><td className={row.group ? "ki-nested" : undefined}>{row.name}</td><td>{valid(row.qty).toLocaleString("en-US")}</td><td className="ki-extra">{Number.isFinite(row.rate) ? format.money(row.rate) : "—"}</td>
                  <td className="ki-extra">{Number.isFinite(row.tax) ? `${Number((row.tax * 100).toFixed(3))}%` : "—"}</td><td>{format.money(row.total)}</td></tr>
              </Fragment>
            ))}</tbody>
          </table>
          <div className="ki-totals"><div><span>Subtotal</span>{format.money(subtotal)}</div><div><span>Tax</span>{format.money(tax)}</div><div className="ki-total"><span>Total</span>{format.money(subtotal + tax)}</div></div>
        </Tabs.Panel>
        <Tabs.Panel value="credit" keepMounted hidden={false} className="ki-sheet" data-front={sheet === "credit"} aria-hidden={sheet !== "credit"} tabIndex={-1}>
          <SheetHead title="Credit note" brand={seller.name}>
            <span>{format.money(creditTotal)} credited{invoiceDate && ` on ${invoiceDate}`}</span>{issued && <span className="ki-issued" role="status">Issued</span>}
          </SheetHead>
          <Terms fields={[
            ["Credit note no", creditNo && <span className="ki-ref">{creditNo}</span>],
            ["Related invoice", invoiceNo && <Button className="ki-link" onClick={() => switchSheet("invoice")}>{invoiceNo}</Button>],
            ["Billing period", period], ["Date of issue", invoiceDate],
          ]} />
          <section className="ki-credits">
            <h3 className="ki-label">Lines to credit</h3>
            <div className="ki-tray">
            <div className="ki-credit-row ki-credit-columns"><span>Name</span><span>Total</span><span>Credit amount</span></div>
            {rows.map(row => (
              <div key={row.id} className="ki-credit-row" data-deselected={!row.selected || undefined}>
                <label className="ki-pick">
                  <Checkbox.Root className="ki-check" aria-label={`Credit ${row.name}`} checked={row.selected} disabled={issued}
                    onCheckedChange={selected => updateLine(row.id, { selected })}>
                    <Checkbox.Indicator><Check aria-hidden="true" /></Checkbox.Indicator>
                  </Checkbox.Root><span>{row.name}</span>
                </label>
                <span className="ki-line-total">{format.money(row.total)}</span>
                <CreditInput amount={row.selected ? row.amount : 0} name={row.name} total={row.total} format={format}
                  disabled={issued || !row.selected} onCommit={amount => updateLine(row.id, { amount })} />
              </div>
            ))}
            </div>
          </section>
          <div className="ki-totals"><div><span>Subtotal</span>{format.money(creditSubtotal)}</div><div><span>Tax</span>{format.money(creditTax)}</div>
            <div className="ki-total"><span>Adjustment total</span>{format.money(-creditTotal)}</div>
            <div className="ki-applied"><span>Applied to invoice</span>{format.money(-creditTotal)} {format.code}</div>
          </div>
          <footer className="ki-footer"><Button className="ki-btn" data-primary={!issued || undefined} disabled={!issued && creditTotal <= 0}
            onClick={() => {
              if (!issued) onIssue?.(Object.fromEntries(credits.map(row => [row.id, row.amount])), creditTotal);
              setIssued(!issued);
            }}>{issued ? "Edit credit note" : "Issue credit note"}</Button></footer>
        </Tabs.Panel>
      </div>
    </Tabs.Root>
  );
}

export function KalosInvoiceCredit(props: InvoiceCreditProps) {
  return <InvoiceDocument key={JSON.stringify([props.invoiceNo, props.creditNo, props.currency])} {...props} />;
}

export function KalosInvoiceCreditPreview({ appearance = "clean" }: Pick<InvoiceCreditProps, "appearance">) {
  return <div className="ki-preview"><div className="ki-preview-inner"><KalosInvoiceCredit appearance={appearance} /></div></div>;
}

.kalos-invoice {
  --ki-paper: var(--card, white);
  --ki-ink: var(--foreground, #202020);
  --ki-text: var(--muted-foreground, #626262);
  --ki-muted: color-mix(in srgb,var(--ki-ink) 53%,transparent);
  --ki-line: var(--border,#00000014);
  --ki-track: var(--muted,#f2f2f2);
  --ki-blue: #0070d6;
  --ki-edge: 0 0 0 .5px var(--ki-line),0 1px 1px -1px #0002,0 1px 2px #0000000c;
  box-sizing: border-box;
  container: invoice / inline-size;
  width: min(100%,760px);
  min-width: 0;
  margin-inline: auto;
  text-align: start;
  font: 400 13px/20px Inter,var(--font-ui,system-ui,sans-serif);
  color: var(--ki-ink);
}
:is(.dark,[data-theme="dark"]) .kalos-invoice {
  --ki-paper: var(--card,#222);
  --ki-ink: var(--foreground,#f4f4f4);
  --ki-text: var(--muted-foreground,#aaa);
  --ki-line: var(--border,#ffffff26);
  --ki-track: var(--muted,#303030);
  --ki-blue: #78baff;
}
.kalos-invoice *, .kalos-invoice *::before { box-sizing: border-box; }
.kalos-invoice :where(h2,h3,dl,dd,p) { margin: 0; }
.kalos-invoice :where(button,input) { border: 0; font: inherit; }
.kalos-invoice button { cursor: pointer; }
.kalos-invoice :where(button,a,[role="checkbox"]):focus-visible { outline: 2px solid var(--ki-blue); outline-offset: 2px; }
.ki-bar,.ki-actions,.ki-tabs,.ki-btn,.ki-sub,.ki-brand,.ki-pick { display: flex; align-items: center; }
.ki-bar { justify-content: space-between; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.ki-actions { gap: 8px; }
.ki-tabs { position: relative; isolation: isolate; padding: 2px; background: var(--ki-track); border-radius: 8px; }
.ki-tabs button { position: relative; min-width: 93px; height: 28px; padding-inline: 12px; border-radius: 6px; color: var(--ki-text); background: transparent; font-weight: 500; }
.ki-tabs [aria-selected="true"] { color: var(--ki-ink); }
.ki-tab-chip { position: absolute; z-index: -1; left: 0; height: 28px; width: var(--active-tab-width); transform: translateX(var(--active-tab-left)); border-radius: 6px; background: var(--ki-paper); box-shadow: var(--ki-edge); transition: transform 240ms cubic-bezier(.22,1,.36,1),width 240ms; }
.ki-btn { gap: 8px; justify-content: center; border-radius: 6px; padding: 0 12px; height: 28px; background: var(--ki-paper); box-shadow: var(--ki-edge); font-weight: 500; color: var(--ki-ink); transition: transform 160ms,background 160ms; }
.ki-btn svg { width: 14px; height: 14px; stroke-width: 1.6; color: var(--ki-text); }
.ki-btn:hover { background: color-mix(in srgb,var(--ki-ink) 4%,var(--ki-paper)); }
.ki-btn:active { transform: translateY(1px); }
.ki-btn:disabled { opacity: .45; cursor: default; }
.ki-stack { display: grid; padding-top: 12px; isolation: isolate; }
.ki-sheet, .ki-sheet[hidden] { display: block; grid-area: 1/1; min-width: 0; border-radius: 12px; padding: 32px 36px 28px; background: var(--ki-paper); box-shadow: var(--ki-edge); transform-origin: center top; transition: transform 620ms cubic-bezier(.22,1,.36,1),opacity 420ms; }
.ki-sheet[data-front="true"] { z-index: 1; }
.ki-sheet[data-front="false"] { transform: translateY(-12px) scale(.965); pointer-events: none; }
.ki-sheet > * { transition: opacity 360ms 180ms; }
.ki-sheet[data-front="false"] > * { opacity: 0; transition-delay: 0s; }
.ki-sheet[data-front="true"][data-starting-style] { animation: ki-draw-sheet 600ms cubic-bezier(.22,1,.36,1); }
@keyframes ki-draw-sheet { 0% { transform: translateY(-12px) scale(.965); } 45% { transform: translateY(3px) scale(.994); } 100% { transform: none; } }
.ki-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 32px; }
.ki-head h2 { color: var(--ki-ink); font-size: 24px; font-weight: 500; letter-spacing: -.035em; line-height: 32px; overflow-wrap: anywhere; }
.ki-sub { margin-top: 4px; min-height: 20px; gap: 4px 12px; flex-wrap: wrap; color: var(--ki-muted); font-size: 12px; line-height: 16px; }
.ki-brand { gap: 8px; flex-shrink: 1; min-width: 0; color: var(--ki-text); font-weight: 500; margin-top: 6px; overflow-wrap: anywhere; }
.ki-brand i { display: grid; place-items: center; width: 20px; height: 20px; flex: none; border-radius: 50%; background: conic-gradient(from 15deg,#8cb4ff,#558cf2,#0045c9,#499cff,#8cb4ff); }
.ki-brand i::after { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--ki-paper); }
.ki-link,.ki-ref { color: var(--ki-blue); font-weight: 500; }
.ki-link { text-decoration: none; padding: 0; background: none; }
.ki-link:hover { text-decoration: underline; }
.ki-parties { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 28px; color: var(--ki-text); }
.ki-parties strong { color: var(--ki-ink); font-weight: 500; }
.ki-label,.ki-items thead th { font-size: 10px; font-weight: 500; line-height: 16px; letter-spacing: .065em; text-transform: uppercase; color: var(--ki-muted); }
.ki-label { margin-bottom: 8px; }
.ki-terms dl { display: grid; gap: 4px; }
.ki-terms dl > div { display: grid; grid-template-columns: minmax(86px,140px) minmax(0,1fr); gap: 12px; }
.ki-terms dt { color: var(--ki-muted); }
.ki-terms dd,.ki-parties p { overflow-wrap: anywhere; }
.ki-items { width: 100%; margin-top: 32px; border-collapse: collapse; font: inherit; color: var(--ki-text); }
.ki-items :where(td,th) { text-align: right; padding: 10px 0 10px 12px; }
.ki-items thead th { padding-block: 0 8px; border-bottom: .5px solid var(--ki-line); }
.ki-items :where(td,th):first-child { text-align: left; padding-left: 0; }
.ki-items :where(td,th):nth-child(2) { text-align: left; }
.ki-items tbody tr:first-child td { padding-top: 14px; }
.ki-items td:first-child,.ki-items td:last-child { color: var(--ki-ink); }
.ki-items td:not(:first-child) { white-space: nowrap; }
.ki-items .ki-group th { text-align: left; padding-block: 16px 4px; font-size: 12px; font-weight: 500; color: var(--ki-ink); }
.ki-items td.ki-nested { padding-left: 16px; }
.ki-totals { display: grid; gap: 6px; width: min(100%,280px); margin: 20px 0 0 auto; font-variant-numeric: tabular-nums; }
.ki-totals > div { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.ki-totals span { color: var(--ki-muted); }
.ki-total { font-weight: 500; border-top: .5px solid var(--ki-line); padding-top: 10px; margin-top: 6px; }
.ki-total span { color: var(--ki-ink); }
.ki-applied { color: var(--ki-text); font-size: 12px; line-height: 16px; }
.ki-credits { margin-top: 28px; }
.ki-credit-row { display: grid; grid-template-columns: minmax(0,1.1fr) minmax(60px,.65fr) minmax(96px,.8fr); align-items: center; gap: 12px; min-height: 48px; }
.ki-credit-row > :not(:first-child) { justify-self: end; }
.ki-credit-row.ki-credit-columns { min-height: 30px; padding-bottom: 4px; color: var(--ki-text); font-size: 12px; line-height: 16px; border-bottom: .5px solid var(--ki-line); }
.ki-credit-columns > :first-child { padding-left: 28px; color: var(--ki-muted); }
.ki-credit-columns > :nth-child(2) { padding-right: 16px; }
.ki-pick { gap: 12px; min-width: 0; overflow-wrap: anywhere; }
.ki-check { display: grid; place-items: center; flex: none; width: 16px; height: 16px; border-radius: 4.5px; cursor: pointer; background: var(--ki-paper); box-shadow: inset 0 0 0 1px var(--ki-line); }
.ki-check[data-checked] { background: var(--ki-blue); box-shadow: none; color: white; }
.ki-check[data-disabled] { cursor: default; }
.ki-check svg { display: block; width: 11px; height: 11px; stroke-width: 2; }
.ki-check svg path { stroke-dasharray: 24; animation: ki-check-in 220ms ease-out; }
@keyframes ki-check-in { from { stroke-dashoffset: 24; } to { stroke-dashoffset: 0; } }
.ki-line-total,.ki-field > span { color: var(--ki-text); }
.ki-credit-row[data-deselected] .ki-pick { color: var(--ki-muted); }
.ki-field { display: flex; align-items: center; justify-content: flex-end; gap: 3px; width: min(100%,120px); height: 28px; padding: 0 8px; border-radius: 6px; background: color-mix(in srgb,var(--ki-ink) 3%,transparent); font-variant-numeric: tabular-nums; }
.ki-field:focus-within { box-shadow: 0 0 0 1px var(--ki-blue); }
.ki-field input { min-width: 0; max-width: calc(100% - 1.5em); text-align: right; padding: 0; outline: none; color: var(--ki-ink); background: transparent; }
.ki-field[data-disabled] { opacity: .6; }
.ki-footer { display: flex; justify-content: flex-end; margin-top: 24px; }
.ki-btn[data-primary] { color: var(--ki-paper); background: var(--ki-ink); }
.ki-issued { color: var(--ki-blue); background: color-mix(in srgb,var(--ki-blue) 9%,transparent); padding: 0 6px; border-radius: 4px; font-size: 11px; }
.kalos-invoice[data-appearance="clean"] {
  & .ki-head h2 { font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
  & .ki-items { margin-top: 28px; }
  & .ki-items thead th { height: 32px; border: 0; box-shadow: inset 0 -.5px var(--ki-line); }
  & .ki-total { padding-top: 12px; border: 0; box-shadow: inset 0 .5px var(--ki-line); }
}
.ki-preview { width: 100%; container: invoice-preview / inline-size; }
.ki-preview-inner { padding: 20px 16px; }
@media (max-width: 860px) { .ki-preview { padding-top: 28px; } }
@container invoice-preview (min-width: 760px) {
  .ki-preview-inner { padding: 32px 0; }
  .ki-preview-inner > .kalos-invoice {
    width: 760px;
    /* Leave 70px beside each edge of the scaled sheet. */
    zoom: min(.82, tan(atan2(calc(100cqw - 140px), 760px)));
  }
}
@container invoice (max-width: 560px) {
  .ki-sheet,.ki-sheet[hidden] { padding: 24px 20px 20px; }
  .ki-head { flex-direction: column-reverse; gap: 12px; }
  .ki-brand { margin-top: 0; }
  .ki-actions .ki-btn:first-child { display: none; }
  .kalos-invoice[data-appearance="clean"] {
    & .ki-head,& .ki-parties { margin-bottom: 24px; }
    & .ki-items,& .ki-credits { margin-top: 24px; }
  }
  .ki-parties { grid-template-columns: minmax(0,1fr); gap: 16px; }
  .ki-extra,.ki-line-total,.ki-credit-columns > :nth-child(2) { display: none; }
  .ki-credit-row { grid-template-columns: minmax(0,1fr) minmax(80px,110px); }
