  & .ki-items .ki-group th { font-size: 14px; font-weight: 400; }
  & .ki-items td.ki-nested { padding-left: 24px; }
  & .ki-totals { width: min(100%,300px); gap: 12px; margin-top: 22px; }
  & .ki-total { padding-top: 14px; margin-top: 4px; border-color: var(--ki-text); }
