  & .ki-credits { background: color-mix(in srgb,var(--ki-ink) 4%,var(--ki-paper)); padding: 0 6px 6px; border-radius: 18px; box-shadow: inset 0 0 0 1px var(--ki-line); }
  & .ki-credits .ki-label { padding: 14px 12px 12px; margin: 0; font-size: 15px; }
  & .ki-tray { padding: 4px 14px; background: var(--ki-paper); box-shadow: var(--ki-edge); border-radius: 14px; }
  & .ki-credit-row { min-height: 60px; gap: 14px; grid-template-columns: minmax(0,1.15fr) minmax(65px,.55fr) minmax(96px,1fr); border-top: 1px solid var(--ki-divider); font-size: 14.5px; }
